package com.cms.controller;
import com.cms.dto.*; import com.cms.entity.User; import com.cms.repository.UserRepository; import com.cms.security.JwtService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {private final AuthenticationManager authenticationManager; private final UserRepository repo; private final JwtService jwt; @PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest r){authenticationManager.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));User u=repo.findByUsername(r.username()).orElseThrow();return new LoginResponse(jwt.generate(u.getUsername(),u.getRole().name()),"Bearer",u.getUsername(),u.getRole().name());}}
